solution.solution.cpp:
#include <random>

int rollDie(std::mt19937& rng)
{
    std::uniform_int_distribution<int> die{ 1, 6 };
    return die(rng);
}

unitTests:
TEST("every roll is between 1 and 6") {
    std::mt19937 rng{ 12345 };
    bool ok{ true };
    for (int i{ 0 }; i < 6000; ++i) { const int r{ rollDie(rng) }; if (r < 1 || r > 6) ok = false; }
    CHECK(ok);
}
TEST("all six faces come up, about equally often") {
    std::mt19937 rng{ 777 };
    int counts[7]{};
    for (int i{ 0 }; i < 6000; ++i) { const int r{ rollDie(rng) }; if (r >= 1 && r <= 6) ++counts[r]; }
    for (int face{ 1 }; face <= 6; ++face) CHECK(counts[face] > 800 && counts[face] < 1200);
}

